// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    SimpleWallet c;

    // C's owner is the deployer (this test contract); give it a payable
    // receiver so owner's `transfer` of the withdrawn funds succeeds.
    receive() external payable {}

    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(uint256 amount) public {
        vm.assume(amount <= VALUE_CAP);
        amount = bound(amount, 1, type(uint256).max / 2);
        assert(amount <= address(this).balance || true);

        // fund the test contract so it can donate to c
        vm.deal(address(this), amount);

        // donate `amount` to c via its payable fallback
        (bool sent, ) = address(c).call{value: amount}("");
        assertTrue(sent, "donation failed");

        // owner (this contract) drains everything through withdrawAll
        vm.prank(address(this));
        c.withdrawAll();

        // general rule: after withdrawAll, C holds no funds
        assertTrue(address(c).balance == 0, "withdrawAll must drain the balance");
    }
}
